sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform shader backdrop;
uniform float blur;
uniform float refraction;
uniform float aberration;
uniform float feature;
uniform float samples;
layout(color) uniform half4 color;
uniform float blend;
uniform float shading;
uniform float intensity;
uniform float shine;
uniform float specularity;
uniform float ambient;
layout(color) uniform half4 light;
uniform float2 direction;
uniform float elevation;
uniform float useLuma;
uniform float amount;
uniform float scale;
uniform float evolution;
uniform float seed;
float hash13(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
float vnoise(float3 p) {
    float3 i = floor(p);
    float3 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = mix(hash13(i), hash13(i + float3(1, 0, 0)), f.x);
    float b = mix(hash13(i + float3(0, 1, 0)), hash13(i + float3(1, 1, 0)), f.x);
    float c = mix(hash13(i + float3(0, 0, 1)), hash13(i + float3(1, 0, 1)), f.x);
    float d = mix(hash13(i + float3(0, 1, 1)), hash13(i + float3(1, 1, 1)), f.x);
    return mix(mix(a, b, f.y), mix(c, d, f.y), f.z);
}
float3 band(int i) {
    if (i == 0) return float3(0.5, 0.0, 1.0);
    if (i == 1) return float3(0.0, 0.0, 1.0);
    if (i == 2) return float3(0.0, 0.6, 1.0);
    if (i == 3) return float3(0.0, 1.0, 0.0);
    if (i == 4) return float3(1.0, 1.0, 0.0);
    if (i == 5) return float3(1.0, 0.5, 0.0);
    return float3(1.0, 0.0, 0.0);
}
float rough(float2 p) {
    float3 q = float3(p / (24.0 * max(scale, 0.01)) + seed * float2(37.1, 17.3), evolution);
    return vnoise(q) * 0.6 + vnoise(q * 2.03 + 5.1) * 0.3 + vnoise(q * 4.1 + 9.7) * 0.1;
}
float height(float2 p) {
    half4 b = blurred.eval(p);
    float h = useLuma > 0.5 ? dot(float3(b.rgb), float3(0.2126, 0.7152, 0.0722)) : float(b.a);
    return amount != 0.0 ? h + amount * (rough(p) - 0.5) * float(b.a) : h;
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return half4(0.0);
    float steps = clamp(floor(samples), 1.0, 20.0);
    float2 g = float2(0.0);
    for (int i = 1; i <= 20; i++) {
        if (float(i) > steps) break;
        float d = float(i);
        g += float2(height(coord + float2(d, 0.0)) - height(coord - float2(d, 0.0)),
                    height(coord + float2(0.0, d)) - height(coord - float2(0.0, d))) / (2.0 * d);
    }
    float3 n = normalize(float3(-g / steps * feature * 0.1, 1.0));
    float3 acc = float3(0.0);
    float alpha = 0.0;
    for (int i = 0; i < 7; i++) {
        half4 s = backdrop.eval(coord - n.xy * (refraction + aberration * (float(i) / 6.0 - 0.5)));
        acc += float3(s.rgb) * band(i);
        alpha += float(s.a) / 7.0;
    }
    float3 rgb = acc / float3(3.5, 3.1, 3.0);
    rgb = mix(rgb, rgb * float3(color.rgb), clamp(blend, 0.0, 1.0));
    if (shading > 0.5) {
        float3 l = normalize(shading < 1.5 ? float3(size * 0.5 + direction - coord, elevation) : float3(direction, elevation));
        float level = max(l.z, 0.05);
        float diffuse = min(max(dot(n, l), 0.0) / level, 2.0);
        float spec = pow(max(dot(reflect(-l, n), float3(0.0, 0.0, 1.0)), 0.0), max(specularity, 1.0)) * shine;
        float3 lc = float3(light.rgb) * intensity;
        rgb = rgb * (ambient + (1.0 - ambient) * diffuse * lc) + spec * lc * max(alpha, 0.5);
        alpha = max(alpha, clamp(spec * intensity, 0.0, 1.0));
    }
    return half4(half3(clamp(rgb, 0.0, alpha)), half(alpha)) * src.a;
}
